<?php declare(strict_types=1);
if(!defined('ABSPATH')) exit;
add_action('after_setup_theme',function(){add_theme_support('woocommerce');add_theme_support('title-tag');add_theme_support('post-thumbnails');add_theme_support('html5',['search-form','gallery','caption']);register_nav_menus(['primary'=>'Primary menu','footer'=>'Footer menu']);});
add_action('wp_enqueue_scripts',function(){wp_enqueue_style('ferreta-reset',get_theme_file_uri('reset.css'),[],'1.0');wp_enqueue_style('ferreta',get_theme_file_uri('assets.css'),['ferreta-reset'],'1.3');wp_enqueue_style('ferreta-hub',get_theme_file_uri('hub.css'),['ferreta'],'1.0');wp_enqueue_style('ferreta-shop',get_theme_file_uri('shop.css'),['ferreta'],'1.1');wp_enqueue_style('ferreta-refinements',get_theme_file_uri('refinements.css'),['ferreta-shop'],'1.0');wp_enqueue_script('ferreta',get_theme_file_uri('assets.js'),[],'1.2',true);wp_enqueue_script('ferreta-refinements',get_theme_file_uri('refinements.js'),['ferreta'],'1.0',true);wp_localize_script('ferreta','Ferreta',['rest'=>rest_url('ferreta/v1/lead'),'cart'=>function_exists('wc_get_cart_url')?wc_get_cart_url():'/cart/','currency'=>'грн']);});
add_filter('woocommerce_show_page_title','__return_false');
add_filter('loop_shop_per_page',fn()=>24);
add_action('wp_head',function(){if(is_product()){global $product;if($product instanceof WC_Product){$schema=['@context'=>'https://schema.org','@type'=>'Product','name'=>$product->get_name(),'sku'=>$product->get_sku(),'offers'=>['@type'=>'Offer','priceCurrency'=>'UAH','price'=>$product->get_price(),'availability'=>$product->is_in_stock()?'https://schema.org/InStock':'https://schema.org/OutOfStock']];echo '<script type="application/ld+json">'.wp_json_encode($schema).'</script>';}}});
